"""Shared string helpers. Used by billing, imports and reports."""
import re


def split_date(text):
    """Split a date string into year, month and day strings."""
    parts = re.split(r'[-./]', text.strip())
    if len(parts) != 3:
        raise ValueError(f"Invalid date format: {text}")
    if len(parts[0]) == 4:
        return parts[0], parts[1], parts[2]
    if len(parts[2]) == 4:
        return parts[2], parts[1], parts[0]
    raise ValueError(f"Could not determine date format: {text}")

